/// Catalog projection of bitview_plugin_pools::Vecs.
pub struct CatalogBitviewPluginPoolsVecs<T0, T1, T2> {
    pub pool: LazyNode<T0>,
    pub major: LazyNode<T1>,
    pub minor: LazyNode<T2>,
}

impl<T0: FromCatalog, T1: FromCatalog, T2: FromCatalog> FromCatalog
    for CatalogBitviewPluginPoolsVecs<T0, T1, T2>
{
    fn from_catalog(client: Arc<BitviewClientBase>, binding: usize) -> Self {
        let CatalogBinding::Branch(children) = &CATALOG_BINDINGS[binding] else {
            unreachable!("expected catalog branch")
        };
        Self {
            pool: lazy_node((client.clone(), children[0]), |(client, binding)| {
                T0::from_catalog(client, binding)
            }),
            major: lazy_node((client.clone(), children[1]), |(client, binding)| {
                T1::from_catalog(client, binding)
            }),
            minor: lazy_node((client.clone(), children[2]), |(client, binding)| {
                T2::from_catalog(client, binding)
            }),
        }
    }
}

